<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tile[gtid.y][gtid.x] = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LoadPixel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dtid.xy);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 各自1ピクセル書く</span></span>
